def findLatestTime(s: str) -> str:
    """
    Generates the latest valid 12-hour format time given a string with missing digits.
    """
    res = list(s)

    # Handle the hour tens digit (index 0)
    # If it is '?', we want the largest valid digit.
    # If the ones digit (index 1) is '?' or small (0-1), we can set tens to '1'.
    # If the ones digit is >= 2, the tens digit must be '0'.
    if res[0] == '?':
        if res[1] == '?' or res[1] in ['0', '1']:
            res[0] = '1'
        else:
            res[0] = '0'

    # Handle the hour ones digit (index 1)
    if res[1] == '?':
        # If tens digit is '0', we can pick up to '9'.
        if res[0] == '0':
            res[1] = '9'
        # If tens digit is '1', we can only pick up to '1'.
        else:
            res[1] = '1'

    # Handle the minute tens digit (index 3)
    if res[3] == '?':
        res[3] = '5'

    # Handle the minute ones digit (index 4)
    if res[4] == '?':
        res[4] = '9'

    return "".join(res)
