def lastNonEmptyString(s: str) -> str:
    from collections import Counter

    counts = Counter(s)

    max_freq = max(counts.values())

    # Find the characters that appear max_freq times
    # These characters will be present in the final string right before it becomes empty
    last_chars = set()
    for char, count in counts.items():
        if count == max_freq:
            last_chars.add(char)

    # Build the result string by finding the last occurrence of each such character
    result = []
    for i in range(len(s) - 1, -1, -1):
        if s[i] in last_chars:
            result.append(s[i])
            last_chars.remove(s[i])
            if not last_chars:
                break

    return "".join(reversed(result))
```

