import sys
from itertools import product

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    INF = float('inf')
    # Initialize adjacency matrix with infinity
    adj = [[INF] * (N + 1) for _ in range(N + 1)]

    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u][v] = w
        except StopIteration:
            break

    # We need to find a walk that visits every vertex at least once.
    # This is equivalent to finding a Hamiltonian path in the meta-graph
    # where edge (u, v) weight is the shortest path distance from u to v in the original graph.

    # Floyd-Warshall to find all-pairs shortest paths.
    # N <= 20, so O(N^3) is very fast.
    dist = [row[:] for row in adj]

    for k in range(1, N + 1):
        for i in range(1, N + 1):
            if dist[i][k] == INF:
                continue
            for j in range(1, N + 1):
                if dist[k][j] == INF:
                    continue
                new_dist = dist[i][k] + dist[k][j]
                if new_dist < dist[i][j]:
                    dist[i][j] = new_dist

    # Check if the graph is strongly connected (or rather, if every vertex is reachable from every other).
    # For a walk to visit all vertices, we must be able to go from any vertex to any other vertex.
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if dist[i][j] == INF:
                print("No")
                return

    # DP over subsets to find the minimum weight Hamiltonian path.
    # dp[s][i] stores the minimum weight to reach vertex i having visited the set of vertices s.
    # s is a bitmask where the k-th bit is 1 if vertex k is visited.

    # Optimization: Iterate over all permutations of vertices (max 20! is too big, so we do DP).
    # Total states: 2^20 * 20 approx 20 million.

    # We will initialize the DP with paths starting at each vertex j.

    dp = [[INF] * (N + 1) for _ in range(1 << N)]

    # Base cases: path of length 0 starting at vertex j (cost 0)
    for j in range(N):
        dp[1 << j][j] = 0

    # Fill DP table
    for mask in range(1, 1 << N):
        for i in range(N):
            if not (mask & (1 << i)):
                continue
            current_cost = dp[mask][i]
            if current_cost == INF:
                continue

            # Try to extend the path to a new vertex j
            for j in range(N):
                if mask & (1 << j):
                    continue

                new_mask = mask | (1 << j)
                # dist is 1-indexed, indices i, j are 0-indexed
                new_cost = current_cost + dist[i + 1][j + 1]

                if new_cost < dp[new_mask][j]:
                    dp[new_mask][j] = new_cost

    # The answer is the minimum cost to reach any vertex j having visited all vertices.
    full_mask = (1 << N) - 1
    ans = INF

    for i in range(N):
        if dp[full_mask][i] < ans:
            ans = dp[full_mask][i]

    print(ans)

if __name__ == "__main__":
    solve()
```

