from functools import lru_cache

def numberOfBeautifulIntegers(low, high, k):
    def solve(N):
        if N == 0:
            return 0
        s = str(N)
        n = len(s)

        @lru_cache(maxsize=None)
        def dp(pos, even_count, odd_count, remainder, is_tight, is_leading_zero):
            if pos == n:
                return 1 if (even_count == odd_count and remainder == 0 and not is_leading_zero) else 0

            limit = int(s[pos]) if is_tight else 9
            total = 0

            for digit in range(limit + 1):
                new_tight = is_tight and (digit == limit)
                new_leading_zero = is_leading_zero and (digit == 0)

                new_even = even_count
                new_odd = odd_count

                if not new_leading_zero:
                    if digit % 2 == 0:
                        new_even += 1
                    else:
                        new_odd += 1

                new_remainder = (remainder * 10 + digit) % k

                total += dp(pos + 1, new_even, new_odd, new_remainder, new_tight, new_leading_zero)

            return total

        # Calculate count of beautiful numbers with exactly n digits
        # is_tight starts as True to respect the upper bound
        # is_leading_zero starts as True to handle leading zeros correctly
        # remainder starts at 0
        # even_count and odd_count start at 0
        return dp(0, 0, 0, 0, True, True)

    # beautiful numbers in [low, high] = beautiful numbers in [0, high] - beautiful numbers in [0, low-1]
    return solve(high) - solve(low - 1)
```

