def medianOfUniquenessArray(nums):
    n = len(nums)
    total_subarrays = n * (n + 1) // 2
    # Median position: the (total_subarrays+1)//2 -th smallest (1-indexed)
    median_pos = (total_subarrays + 1) // 2

    def count_at_most_k(k):
        # Count subarrays with at most k distinct elements
        if k == 0:
            return 0
        count = 0
        freq = {}
        left = 0
        for right in range(n):
            freq[nums[right]] = freq.get(nums[right], 0) + 1
            while len(freq) > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1
            count += right - left + 1
        return count

    # Binary search for the smallest value m such that count_at_most_k(m) >= median_pos
    lo, hi = 1, len(set(nums))
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most_k(mid) >= median_pos:
            hi = mid
        else:
            lo = mid + 1
    return lo
