import sys
from collections import deque

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    # BFS to establish parent-child relationships rooted at 1
    parent = [0] * (N + 1)
    order = []
    visited = [False] * (N + 1)

    queue = deque([1])
    visited[1] = True

    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                queue.append(v)

    # reverse order to process leaves up to root
    order.reverse()

    # dp[v] stores the cost to eliminate the subtree rooted at v (where v != 1)
    # For v = 1, we compute the answer directly
    dp = [0] * (N + 1)

    for u in order:
        children = []
        for v in adj[u]:
            if v != parent[u]:
                children.append(v)

        if u == 1:
            # Calculate answer for root
            if not children:
                print(1)
                return

            has_leaf_child = False
            ans = 0

            for v in children:
                # v is a direct child of 1
                # Check if v is a leaf in the subtree (i.e., v has no children)
                is_leaf = True
                for w in adj[v]:
                    if w != u:
                        is_leaf = False
                        break

                if is_leaf:
                    has_leaf_child = True
                else:
                    ans = max(ans, dp[v] + 1)

            if has_leaf_child:
                print(1)
            else:
                print(ans)
            return
        else:
            # Calculate cost for non-root node u
            if not children:
                dp[u] = 1
            else:
                has_leaf_child = False
                min_cost = float('inf')

                for v in children:
                    # Check if v is a leaf in the subtree
                    is_leaf = True
                    for w in adj[v]:
                        if w != u:
                            is_leaf = False
                            break

                    if is_leaf:
                        has_leaf_child = True
                    else:
                        min_cost = min(min_cost, dp[v])

                if has_leaf_child:
                    dp[u] = 1
                else:
                    dp[u] = 1 + min_cost

if __name__ == '__main__':
    solve()
