def minimumString(a: str, b: str, c: str) -> str:
    def merge(s1, s2):
        if s2 in s1:
            return s1
        if s1 in s2:
            return s2
        for i in range(len(s1), -1, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    from itertools import permutations

    best = None
    for p in permutations([a, b, c]):
        s = merge(merge(p[0], p[1]), p[2])
        if best is None or (len(s), s) < (len(best), best):
            best = s
    return best
