import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Initialize the reachability matrix.
    # reachability[i][j] will be True if there is a path from person i to person j
    # following the "stronger than" direction (i -> j).
    reachability = [[False] * (N + 1) for _ in range(N + 1)]

    # Read the M pieces of information
    for _ in range(M):
        try:
            A = int(next(iterator))
            B = int(next(iterator))
            # A is stronger than B, so edge A -> B
            reachability[A][B] = True
        except StopIteration:
            break

    # Compute transitive closure using Floyd-Warshall algorithm.
    # If there are paths x -> k and k -> y, then x -> y.
    # N is at most 50, so O(N^3) is very efficient.
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            if reachability[i][k]:
                for j in range(1, N + 1):
                    if reachability[k][j]:
                        reachability[i][j] = True

    # Determine the strongest programmer.
    # The strongest programmer is the one who is stronger than all other N-1 people.
    # Based on the constraints (a total order exists), there is at most one such person.
    # If multiple people appear to be strongest candidates (due to lack of information), 
    # we must print -1.

    candidate = -1
    candidate_count = 0

    for person in range(1, N + 1):
        is_strongest = True
        for other in range(1, N + 1):
            if person == other:
                continue
            # If person is not stronger than other, they cannot be the strongest
            if not reachability[person][other]:
                is_strongest = False
                break

        if is_strongest:
            candidate_count += 1
            candidate = person

    # If there is exactly one candidate, print their number. Otherwise print -1.
    if candidate_count == 1:
        print(candidate)
    else:
        print(-1)

if __name__ == '__main__':
    solve()
