def main():
    # Read all input from standard input at once
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    products = []

    # Parse the product data
    for _ in range(N):
        try:
            P = int(next(iterator))
            C = int(next(iterator))
            functions = set()
            # Read C function indices and store them in a set for O(1) lookups and subset checks
            for _ in range(C):
                functions.add(int(next(iterator)))
            products.append((P, functions))
        except StopIteration:
            break

    found_superior = False

    # Iterate through all ordered pairs (i, j) with i != j
    for i in range(N):
        if found_superior:
            break
        for j in range(N):
            if i == j:
                continue

            P_i, F_i = products[i]
            P_j, F_j = products[j]

            # Condition 1: P_i >= P_j
            if P_i < P_j:
                continue

            # Condition 2: The j-th product has all functions of the i-th product
            # This means F_i must be a subset of F_j
            if not F_i.issubset(F_j):
                continue

            # Condition 3: P_i > P_j OR the j-th product has one or more functions that the i-th product lacks
            # (F_j has functions F_i lacks) is equivalent to F_j not being a subset of F_i
            # Since F_i is already a subset of F_j (checked above), this is equivalent to F_i != F_j
            if P_i > P_j or F_i != F_j:
                found_superior = True
                break

    if found_superior:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    main()
