class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            # Helper function to check if string s can be partitioned to sum to target.
            # Uses recursion with memoization.
            # State is defined by (current_index, current_sum).

            memo = {}

            def backtrack(index, current_sum):
                if index == len(s):
                    return current_sum == target

                if (index, current_sum) in memo:
                    return memo[(index, current_sum)]

                # Pruning: if current_sum already exceeds target, further addition will only increase it.
                if current_sum > target:
                    memo[(index, current_sum)] = False
                    return False

                num = 0
                for j in range(index, len(s)):
                    num = num * 10 + int(s[j])

                    if backtrack(j + 1, current_sum + num):
                        memo[(index, current_sum)] = True
                        return True

                memo[(index, current_sum)] = False
                return False

            return backtrack(0, 0)

        total_punishment = 0

        for i in range(1, n + 1):
            square_val = i * i
            # Convert square to string to perform partitioning
            square_str = str(square_val)

            if can_partition(square_str, i):
                total_punishment += square_val

        return total_punishment
