import sys

def solve():
    # Read all input from stdin at once
    input = sys.stdin.read().split()

    if not input:
        return

    # Parse H, W, K
    iterator = iter(input)
    try:
        H = int(next(iterator))
        W = int(next(iterator))
        K = int(next(iterator))
    except StopIteration:
        return

    S = []
    # Collect the H strings
    for _ in range(H):
        try:
            S.append(next(iterator))
        except StopIteration:
            break

    min_ops = float('inf')

    # Check horizontal sequences
    if K <= W:
        # Iterate through each row
        for r in range(H):
            # Extend the row with K-1 'x's to simplify the sliding window check.
            # This ensures any window containing a real 'x' is invalid, while windows
            # containing only the padding 'x's (and fewer than K real characters) 
            # are also invalid or out of bounds.
            s = S[r] + 'x' * (K - 1)
            count_dot = 0
            count_o = 0

            # First window [0, K-1]
            for char in s[:K]:
                if char == '.':
                    count_dot += 1
                elif char == 'o':
                    count_o += 1

            # Check if first window is valid
            if count_o + count_dot == K:
                min_ops = min(min_ops, count_dot)

            # Slide the window
            for j in range(1, W):
                # Remove the character leaving the window (s[j-1])
                prev_char = s[j-1]
                if prev_char == '.':
                    count_dot -= 1
                elif prev_char == 'o':
                    count_o -= 1

                # Add the character entering the window (s[j+K-1])
                next_char = s[j+K-1]
                if next_char == '.':
                    count_dot += 1
                elif next_char == 'o':
                    count_o += 1

                # Check validity
                if count_o + count_dot == K:
                    min_ops = min(min_ops, count_dot)

    # Check vertical sequences
    if K <= H:
        # Iterate through each column
        for c in range(W):
            # Build the string for the column
            col_str = []
            for r in range(H):
                col_str.append(S[r][c])
            s = "".join(col_str) + 'x' * (K - 1)
            count_dot = 0
            count_o = 0

            # First window
            for char in s[:K]:
                if char == '.':
                    count_dot += 1
                elif char == 'o':
                    count_o += 1

            if count_o + count_dot == K:
                min_ops = min(min_ops, count_dot)

            # Slide the window
            for i in range(1, H):
                prev_char = s[i-1]
                if prev_char == '.':
                    count_dot -= 1
                elif prev_char == 'o':
                    count_o -= 1

                next_char = s[i+K-1]
                if next_char == '.':
                    count_dot += 1
                elif next_char == 'o':
                    count_o += 1

                if count_o + count_dot == K:
                    min_ops = min(min_ops, count_dot)

    if min_ops == float('inf'):
        print(-1)
    else:
        print(min_ops)

if __name__ == '__main__':
    solve()
