```python
def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False

    parent = list(range(n))
    rank = [1] * n

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1

    # Precompute Smallest Prime Factors (SPF) using Sieve of Eratosthenes
    MAX_VAL = 100001
    spf = list(range(MAX_VAL))
    i = 2
    while i * i < MAX_VAL:
        if spf[i] == i:
            for j in range(i * i, MAX_VAL, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1

    prime_to_index = {}

    for index, x in enumerate(nums):
        temp = x
        while temp > 1:
            p = spf[temp]
            if p in prime_to_index:
                union(index, prime_to_index[p])
            else:
                prime_to_index[p] = index
            while temp % p == 0:
                temp //= p

    # Check if all indices are connected to the first index
    target_root = find(0)
    for i in range(1, n):
        if find(i) != target_root:
            return False

    return True
```

To solve this problem, we need to identify the prime numbers in the input array `nums`, find their indices, and then calculate the maximum distance between any two of these indices. Since the numbers in the array are constrained between 1 and 100, we can efficiently check for primality using a precomputed set or simple trial division. To find the maximum distance between indices, we simply need the difference between the maximum index and the minimum index where a prime number occurs.

Here is the executable Python function:

```python
def maximumPrimeDifference(nums):
    # Helper function to determine if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check for factors from 3 up to the square root of n
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all indices where the number is prime
    prime_indices = [i for i, x in enumerate(nums) if is_prime(x)]

    # The maximum distance is the difference between the last and first prime index
    return prime_indices[-1] - prime_indices[0]
